 */

/* ===== src/kernel/scrollbars.css ===== */
/* Hide scrollbar appearance only; scrolling and range inputs remain functional. */
::-webkit-scrollbar {
  display: none !important;
}

* {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

/* ===== src/tokens.css ===== */
/*
 * 柠页 UI Theme
 * Author: @jiuyi0204
 * 未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。
 */

@font-face {
  font-family: "Huiwen-mincho";
  src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/huiwenmincho-improved/HuiwenMincho-Improved-Regular.woff2") format("woff2");
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}

:root {
  --ningye-paper: #f5f0df;
  --ningye-paper-deep: #e8dfc4;
  --ningye-paper-panel: rgba(247, 242, 224, .975);
  --ningye-ink: #344631;
  --ningye-ink-soft: #65715e;
  --ningye-sage: #70885d;
  --ningye-sage-light: #b9c6a5;
  --ningye-citrus: #d9c75f;
  --ningye-citrus-soft: #f0e7a9;
  --ningye-clay: #a25e4b;
  --ningye-info: #5d7881;
  --ningye-success: #617d4f;
  --ningye-warning: #a77b32;
  --ningye-error: #9d5148;
  --ningye-line: rgba(79, 101, 66, .42);
  --ningye-line-soft: rgba(79, 101, 66, .19);
  --ningye-shadow: 0 .45rem 1.35rem rgba(67, 79, 50, .18);
  --ningye-shadow-soft: 0 .18rem .55rem rgba(67, 79, 50, .13);
  --ningye-glow: 0 0 .55rem rgba(244, 213, 91, .58), 0 0 1.15rem rgba(244, 213, 91, .24);
  --ningye-glow-soft: 0 0 .42rem rgba(244, 213, 91, .3);
  --ningye-radius-sm: .25rem;
  --ningye-radius: .55rem;
  --ningye-space: clamp(.75rem, 1.3vw, 1.25rem);
  --ningye-font: "Huiwen-mincho", "Noto Serif SC", "Songti SC", SimSun, serif;
  --ningye-paper-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/fc6f656f87691efcfbf62432ef4141f4da3a7baf/assets/%E6%9F%A0%E9%A1%B5/ningye-paper.png");
  --ningye-glow-trinket-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/8c7358f604d15f93c806193d60f5585007502e30/assets/%E6%9F%A0%E9%A1%B5/ningye-glow-trinket.png");
  --ningye-avatar-size: 4.1rem;
  --ningye-avatar-gap: .75rem;
  --ningye-avatar-slot: calc(var(--ningye-avatar-size) + var(--ningye-avatar-gap));
  --ningye-avatar-head-height: calc(var(--ningye-avatar-size) + 2.4rem);
}

body {
  --SmartThemeBodyColor: var(--ningye-ink);
  --SmartThemeEmColor: var(--ningye-clay);
  --SmartThemeQuoteColor: var(--ningye-sage);
  --SmartThemeBorderColor: var(--ningye-line);
  --SmartThemeBlurTintColor: var(--ningye-paper-panel);
  --SmartThemeChatTintColor: rgba(245, 240, 223, .94);
  --SmartThemeUserMesBlurTintColor: rgba(240, 231, 169, .32);
  --SmartThemeBotMesBlurTintColor: rgba(245, 240, 223, .08);
  --SmartThemeShadowColor: transparent;
  font-family: var(--ningye-font);
  color: var(--ningye-ink);
  background-color: #72845f;
}

:is(
  #chat,
  #top-settings-holder,
  #send_form,
  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel,
  .popup,
  #options,
  #extensionsMenu
) {
  font-family: var(--ningye-font);
}

::selection {
  color: #263222;
  background: rgba(217, 199, 95, .58);
}

:is(
  #chat,
  #top-settings-holder,
  #send_form,
  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel,
  .popup,
  #options,
  #extensionsMenu
) :focus-visible {
  outline: 2px solid var(--ningye-citrus);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  :is(#chat, #top-settings-holder, #send_form, .drawer-content, .popup, #options, #extensionsMenu) *,
  :is(#chat, #top-settings-holder, #send_form, .drawer-content, .popup, #options, #extensionsMenu) *::before,
  :is(#chat, #top-settings-holder, #send_form, .drawer-content, .popup, #options, #extensionsMenu) *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}

/* ===== src/chat-layout.css ===== */
/* W01 — flat single-page library journal; structure gate confirmed. */

#chat {
  box-sizing: border-box;
  isolation: isolate;
  gap: 0;
  padding: clamp(1.1rem, 2.3vw, 2.5rem) clamp(1rem, 4.4vw, 4.75rem) 1.5rem;
  color: var(--ningye-ink);
  background-color: var(--ningye-paper);
  background-image: var(--ningye-glow-trinket-image), var(--ningye-paper-image);
  background-size: clamp(4.2rem, 7vw, 6.2rem) auto, cover;
  background-position: right .65rem top .75rem, center top;
  background-repeat: no-repeat, no-repeat;
  border: 1px solid rgba(72, 92, 59, .35);
  border-radius: var(--ningye-radius-sm) var(--ningye-radius-sm) 0 0;
  box-shadow: var(--ningye-shadow);
  text-shadow: none;
  overflow-x: hidden;
}

#chat .mes {
  display: block;
  box-sizing: border-box;
  position: relative;
  width: min(100%, 74rem);
  margin-inline: auto;
  padding: clamp(1rem, 2vw, 1.7rem) 0 clamp(1.15rem, 2vw, 1.85rem);
  color: var(--ningye-ink);
  background: transparent;
  border: 0;
  border-radius: 0;
}

#chat .mes + .mes[is_system="false"]::before {
  content: "";
  display: block;
  height: 1px;
  margin: 0 0 clamp(1rem, 2vw, 1.6rem);
  background: linear-gradient(90deg, transparent, var(--ningye-line), transparent);
}

#chat .mes_block {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  margin: 0;
  padding: 0;
  overflow: visible;
}

#chat .mes[is_user="true"] .mes_block {
  width: min(76%, 46rem);
  margin-inline: auto 0;
  padding: .85rem 1rem .95rem;
  background: linear-gradient(105deg, rgba(240, 231, 169, .68), rgba(249, 244, 217, .68));
  border-left: .22rem solid var(--ningye-citrus);
  border-bottom: 1px solid rgba(115, 124, 71, .34);
  box-shadow: var(--ningye-shadow-soft);
}

#chat .ch_name {
  box-sizing: border-box;
  min-height: var(--ningye-avatar-head-height);
  padding: .1rem var(--ningye-avatar-slot) .55rem 0;
  align-items: flex-start;
  border-bottom: 1px dashed var(--ningye-line);
}

#chat .mes[is_user="true"] .ch_name {
  min-height: calc(var(--ningye-avatar-size) + 1.5rem);
}

#chat .ch_name .name_text {
  color: var(--ningye-sage);
  font-family: var(--ningye-font);
  font-size: 1.05em;
  font-weight: 400;
  letter-spacing: .11em;
  text-transform: uppercase;
}

#chat .ch_name .timestamp,
#chat .ch_name .timestamp-icon {
  color: var(--ningye-ink-soft);
  font-size: .78em;
  opacity: .88;
}

#chat .mesAvatarWrapper {
  position: absolute;
  z-index: 2;
  top: clamp(1rem, 2vw, 1.7rem);
  right: 0;
  width: var(--ningye-avatar-size);
  min-width: var(--ningye-avatar-size);
  padding: 0;
  color: var(--ningye-ink-soft);
  text-align: center;
}

#chat .mes + .mes[is_system="false"] .mesAvatarWrapper {
  top: calc(clamp(1rem, 2vw, 1.7rem) + clamp(1rem, 2vw, 1.6rem) + 1px);
}

#chat .mesAvatarWrapper .avatar,
#chat .mesAvatarWrapper .avatar img {
  box-sizing: border-box;
  width: var(--ningye-avatar-size);
  height: var(--ningye-avatar-size);
  min-width: var(--ningye-avatar-size);
  border-radius: .22rem;
}

#chat .mesAvatarWrapper .avatar {
  padding: .23rem;
  background: var(--ningye-paper);
  border: 1px dashed rgba(78, 101, 64, .58);
  box-shadow: .18rem .22rem 0 rgba(112, 136, 93, .23);
  transform: rotate(1.6deg);
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar {
  transform: rotate(-1.4deg);
}

#chat .mesAvatarWrapper .avatar img {
  object-fit: cover;
  border: 1px solid rgba(78, 101, 64, .48);
  box-shadow: none;
}

#chat .mesIDDisplay,
#chat .mes_timer,
#chat .tokenCounterDisplay {
  margin-top: .18rem;
  color: var(--ningye-ink-soft);
  font-size: .68em;
  line-height: 1.2;
  opacity: .82;
}

#chat .mes_buttons,
#chat .mes_edit_buttons,
#chat .mes_reasoning_actions {
  color: var(--ningye-sage);
  text-shadow: none;
  filter: none;
}

#chat .mes_button,
#chat .extraMesButtons > div,
#chat .mes_edit_buttons,
#chat .mes_edit_buttons .menu_button,
#chat .mes_reasoning_actions .menu_button {
  box-shadow: none;
  filter: none;
  text-shadow: none;
}

#chat .mes_button,
#chat .mes_edit_buttons .menu_button,
#chat .mes_reasoning_actions .menu_button {
  opacity: .72;
  transition: color .16s ease, opacity .16s ease, transform .16s ease;
}

#chat .mes_button:hover,
#chat .mes_button:focus-visible,
#chat .mes_edit_buttons .menu_button:hover,
#chat .mes_reasoning_actions .menu_button:hover {
  color: var(--ningye-clay);
  opacity: 1;
  transform: translateY(-1px);
  filter: none;
  box-shadow: none;
  text-shadow: none;
}

#chat .mes_reasoning_details {
  margin: .85rem 0;
  padding: 0;
  color: var(--ningye-ink-soft);
  background: transparent;
  border: 0;
  border-radius: var(--ningye-radius-sm);
}

#chat .mes_reasoning_details .mes_reasoning_summary {
  margin-right: 0;
  align-items: center;
  background: transparent;
}

#chat .mes_reasoning_details .mes_reasoning_header {
  box-sizing: border-box;
  min-height: 2.65rem;
  margin: 0;
  padding: .52rem 4.25rem .52rem .78rem;
  color: var(--ningye-sage);
  background-color: rgba(250, 247, 229, .96) !important;
  background-image: var(--ningye-glow-trinket-image);
  background-position: right 1.85rem center;
  background-repeat: no-repeat;
  background-size: 2.15rem auto;
  border: 1px solid var(--ningye-line);
  border-left: .22rem solid var(--ningye-citrus);
  border-radius: var(--ningye-radius-sm);
  box-shadow: var(--ningye-shadow-soft), var(--ningye-glow-soft);
  text-shadow: 0 0 .45rem rgba(244, 213, 91, .22);
}

#chat .mes_reasoning_details[open] .mes_reasoning_header {
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}

#chat .mes_reasoning_details .mes_reasoning {
  margin: 0;
  padding: .75rem .9rem .8rem;
  color: var(--ningye-ink-soft) !important;
  background: rgba(248, 244, 225, .88);
  border: 1px solid var(--ningye-line-soft);
  border-top: 0;
  border-left: .22rem solid var(--ningye-sage-light);
  border-radius: 0 0 var(--ningye-radius-sm) var(--ningye-radius-sm);
}

#chat .mes_reasoning_details .mes_reasoning_arrow {
  color: var(--ningye-sage);
  filter: none;
  text-shadow: var(--ningye-glow-soft);
}

#chat .mes_reasoning_header_title {
  color: var(--ningye-sage);
  font-weight: 400;
  letter-spacing: .06em;
}

#chat .mes[is_system="true"] {
  width: min(92%, 54rem);
  margin-block: .45rem;
  padding: .55rem .8rem;
  color: var(--ningye-info);
  background: rgba(218, 228, 216, .62);
  border: 1px dashed rgba(93, 120, 129, .5);
}

#chat .mes.smallSysMes {
  width: fit-content;
  max-width: 92%;
  margin-inline: auto;
}

#chat .swipe_left,
#chat .swipe_right,
#chat .swipes-counter {
  color: var(--ningye-sage);
  text-shadow: none;
}

#chat .mes.selected {
  background: rgba(217, 199, 95, .2);
  outline: 1px dashed var(--ningye-citrus);
}

/* ===== src/full-text.css ===== */
/* T01 — traditional long-form reading; never repairs avatar geometry. */

#chat .mes_text {
  box-sizing: border-box;
  max-width: 100%;
  padding: .72rem 0 .2rem;
  color: var(--ningye-ink);
  font-family: var(--ningye-font);
  font-size: 1em;
  font-weight: 400;
  line-height: 1.9;
  letter-spacing: .018em;
  overflow-wrap: anywhere;
}

#chat .mes[is_user="true"] .mes_text {
  padding-top: .5rem;
  font-size: .96em;
  line-height: 1.72;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text > p {
  margin: .72em 0;
  text-indent: 2em;
}

#chat .mes_text > p:first-child {
  margin-top: .25em;
}

#chat .mes_text h1,
#chat .mes_text h2,
#chat .mes_text h3,
#chat .mes_text h4 {
  color: var(--ningye-sage);
  font-family: var(--ningye-font);
  font-weight: 400;
  letter-spacing: .08em;
  line-height: 1.35;
}

#chat .mes_text h1 {
  font-size: 1.62em;
  border-bottom: 1px solid var(--ningye-line);
}

#chat .mes_text h2 { font-size: 1.34em; }
#chat .mes_text h3 { font-size: 1.16em; }
#chat .mes_text h4 { font-size: 1.04em; }

#chat .mes_text strong {
  color: var(--ningye-clay);
  font-weight: 400;
  text-decoration: underline;
  text-decoration-color: rgba(217, 199, 95, .74);
  text-decoration-thickness: .18em;
  text-underline-offset: -.05em;
  text-decoration-skip-ink: none;
}

#chat .mes_text em {
  color: var(--ningye-sage);
}

#chat .mes_text blockquote {
  margin: 1em .5em;
  padding: .7em 1em;
  color: var(--ningye-ink-soft);
  background: rgba(233, 226, 198, .62);
  border: 0;
  border-left: .22rem solid var(--ningye-citrus);
}

#chat .mes_text ul,
#chat .mes_text ol {
  padding-inline-start: 1.8em;
}

#chat .mes_text li::marker {
  color: var(--ningye-sage);
}

#chat .mes_text a {
  color: #526d48;
  text-decoration-color: var(--ningye-citrus);
  text-underline-offset: .18em;
}

#chat .mes_text code {
  color: #40523c;
  background: rgba(249, 245, 224, .9);
  border: 1px solid rgba(217, 199, 95, .34);
  border-radius: .2rem;
  box-shadow: inset 0 0 .45rem rgba(244, 213, 91, .12);
}

#chat .mes_text pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9rem 1rem;
  color: #344631;
  background: linear-gradient(110deg, rgba(250, 247, 230, .96), rgba(239, 243, 220, .9));
  border: 1px solid rgba(112, 136, 93, .36);
  border-radius: var(--ningye-radius-sm);
  box-shadow: inset .2rem 0 0 var(--ningye-citrus), var(--ningye-glow-soft);
}

#chat .mes_text table {
  display: block;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  background: rgba(250, 247, 233, .72);
}

#chat .mes_text th,
#chat .mes_text td {
  padding: .5em .7em;
  border: 1px solid var(--ningye-line);
}

#chat .mes_text th {
  color: var(--ningye-sage);
  font-weight: 400;
  background: rgba(220, 226, 201, .72);
}

#chat .mes_text hr {
  height: 1px;
  margin: 1.5em 0;
  background: linear-gradient(90deg, transparent, var(--ningye-sage), var(--ningye-citrus), transparent);
  opacity: .68;
}

#chat .mes_text img,
#chat .mes_media_wrapper img,
#chat .mes_media_wrapper video {
  max-width: 100%;
  border: .35rem solid rgba(250, 247, 233, .9);
  box-shadow: var(--ningye-shadow-soft);
}

#chat .mes_file_wrapper {
  color: var(--ningye-ink-soft);
  background: rgba(240, 231, 169, .3);
  border: 1px dashed var(--ningye-line);
}

#chat .mes_text details {
  margin: .8rem 0;
  padding: .6rem .75rem;
  background: rgba(235, 231, 208, .68);
  border: 1px dashed var(--ningye-line);
}

/* ===== src/windows/topbar.css ===== */
/* W02 — botanical bookmark index, nine original semantic icons retained. */
#top-bar {
  background: rgba(245, 240, 223, .96);
  border-bottom: 1px solid var(--ningye-line);
  box-shadow: 0 .25rem .85rem rgba(66, 80, 52, .16);
  backdrop-filter: none;
}

#top-settings-holder {
  box-sizing: border-box;
  padding-inline: .35rem;
  color: var(--ningye-sage);
  background: linear-gradient(180deg, rgba(249, 246, 233, .98), rgba(235, 229, 204, .96));
  border-bottom: 1px solid var(--ningye-line);
  box-shadow: 0 .2rem .65rem rgba(66, 80, 52, .14);
}

#top-settings-holder > .drawer {
  background: transparent;
}

#top-settings-holder .drawer-toggle {
  min-width: var(--topBarBlockSize);
  min-height: var(--topBarBlockSize);
  color: var(--ningye-sage);
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  transition: color .16s ease, transform .16s ease;
}

#top-settings-holder .drawer-toggle:hover,
#top-settings-holder .drawer-toggle:focus-within,
#top-settings-holder .drawer-toggle:has(.openIcon) {
  color: var(--ningye-clay);
  transform: translateY(-1px);
  filter: none;
}

#top-settings-holder .drawer-icon.fa-solid,
#top-settings-holder .drawer-icon.fas {
  display: inline-block;
  font-family: "Font Awesome 6 Free";
  font-style: normal;
  font-weight: 900;
  font-size: var(--topBarIconSize);
  line-height: 1;
  color: inherit;
  opacity: .9;
  filter: none;
  visibility: visible;
  text-shadow: none;
}

#top-settings-holder .drawer-icon.fa-solid::before,
#top-settings-holder .drawer-icon.fas::before {
  font-family: "Font Awesome 6 Free";
  font-style: normal;
  font-weight: 900;
  color: inherit;
  opacity: 1;
  visibility: visible;
}

/* 1.14.0 topbar semantic glyphs: ID-scoped content survives icon-class redraw races. */
#leftNavDrawerIcon::before { content: "\f1de"; }
#API-status-top::before { content: "\e55d"; }
#advanced-formatting-button .drawer-icon::before { content: "\f031"; }
#WIDrawerIcon::before { content: "\f558"; }
#user-settings-button .drawer-icon::before { content: "\f4fe"; }
#backgrounds-button .drawer-icon::before { content: "\e209"; }
#extensions-settings-button .drawer-icon::before { content: "\f1b3"; }
#persona-management-button .drawer-icon::before { content: "\f118"; }
#rightNavDrawerIcon::before { content: "\f2bb"; }

#top-settings-holder .drawer-toggle:hover .drawer-icon,
#top-settings-holder .drawer-toggle:focus-within .drawer-icon,
#top-settings-holder .drawer-toggle:has(.openIcon) .drawer-icon {
  opacity: 1;
  text-shadow: var(--ningye-glow);
}

/* ===== src/windows/input.css ===== */
/* W03 — library checkout card. */
#send_form {
  box-sizing: border-box;
  position: relative;
  margin-top: .35rem;
  color: var(--ningye-ink);
  background: linear-gradient(90deg, rgba(237, 231, 204, .98), rgba(249, 245, 229, .98));
  border: 1px solid var(--ningye-line);
  border-top: .22rem double rgba(112, 136, 93, .55);
  border-radius: 0 0 var(--ningye-radius) var(--ningye-radius);
  box-shadow: var(--ningye-shadow);
  backdrop-filter: none;
}

#send_form #nonQRFormItems {
  align-items: stretch;
  column-gap: .35rem;
}

#send_form #send_textarea {
  color: var(--ningye-ink);
  font-family: var(--ningye-font);
  font-size: 1em;
  line-height: 1.55;
  background: rgba(252, 249, 236, .6);
  border: 0;
  border-left: 1px dashed var(--ningye-line);
  border-right: 1px dashed var(--ningye-line);
  border-radius: 0;
  text-shadow: none;
}

#send_form #send_textarea::placeholder {
  color: var(--ningye-ink-soft);
  opacity: .74;
}

#send_form:has(#send_textarea:focus-visible) {
  border-color: var(--ningye-citrus);
  outline: 1px solid rgba(217, 199, 95, .7);
}

#send_form #leftSendForm,
#send_form #rightSendForm {
  align-items: center;
}

#send_form #leftSendForm > div,
#send_form #rightSendForm > div {
  color: var(--ningye-sage);
  opacity: .86;
  background: transparent;
  border: 0;
  border-radius: 0;
  text-shadow: none;
  filter: none;
}

#send_form #leftSendForm > div:hover,
#send_form #rightSendForm > div:hover,
#send_form #leftSendForm > div:focus-visible,
#send_form #rightSendForm > div:focus-visible {
  color: var(--ningye-clay);
  opacity: 1;
  background: rgba(217, 199, 95, .18);
  transform: translateY(-1px);
  filter: none;
}

#send_form #send_but { color: #4f7449; font-size: 1.15em; }
