#rm_extensions_block .inline-drawer {
  margin-block: .28rem;
}

#rm_extensions_block .inline-drawer-header,
#rm_extensions_block .extension_block > .inline-drawer-header {
  box-sizing: border-box;
  min-height: 2.45rem;
  padding: .42rem .58rem;
  color: var(--ningye-sage) !important;
  background: linear-gradient(96deg, rgba(250, 247, 229, .98), rgba(235, 240, 216, .92)) !important;
  border: 1px solid var(--ningye-line-soft);
  border-left: .22rem solid var(--ningye-citrus);
  border-radius: var(--ningye-radius-sm);
  box-shadow: 0 .1rem .34rem rgba(67, 79, 50, .1), inset 0 0 .8rem rgba(244, 213, 91, .1);
  text-shadow: 0 0 .45rem rgba(244, 213, 91, .2);
}

#rm_extensions_block .inline-drawer-header:hover,
#rm_extensions_block .inline-drawer-header:focus-within {
  color: var(--ningye-clay) !important;
  border-color: rgba(217, 199, 95, .7);
  box-shadow: var(--ningye-shadow-soft), var(--ningye-glow-soft);
}

#rm_extensions_block .inline-drawer-icon {
  color: var(--ningye-sage);
  opacity: .9;
  filter: none;
  text-shadow: var(--ningye-glow-soft);
}

#rm_extensions_block .inline-drawer-content {
  margin: 0 .24rem .38rem;
  padding: .6rem .7rem;
  color: var(--ningye-ink-soft);
  background: rgba(249, 246, 230, .9);
  border: 1px solid var(--ningye-line-soft);
  border-top: 0;
  border-radius: 0 0 var(--ningye-radius-sm) var(--ningye-radius-sm);
}

#rm_extensions_block :is(.menu_button, button) { color: var(--ningye-sage); background: rgba(230, 226, 202, .8); border-color: var(--ningye-line); }
#rm_extensions_block :is(.menu_button, button):hover { color: var(--ningye-clay); background: rgba(217, 199, 95, .2); }

/* ===== src/windows/persona.css ===== */
/* W11 — persona identity card folio. */
#PersonaManagement {
  color: var(--ningye-ink);
  background: var(--ningye-paper-panel);
  border-left: .24rem solid var(--ningye-citrus);
}

#PersonaManagement :is(h3, h4, .inline-drawer-header) { color: var(--ningye-sage); font-weight: 400; }

#PersonaManagement h4.standoutHeader {
  box-sizing: border-box;
  color: var(--ningye-sage);
  background-color: rgba(250, 247, 229, .97);
  background-image: none;
  border: 1px solid var(--ningye-line-soft);
  border-left: .22rem solid var(--ningye-citrus);
  border-radius: var(--ningye-radius-sm);
  box-shadow: var(--ningye-shadow-soft), inset 0 0 .75rem rgba(244, 213, 91, .08);
  filter: none;
  text-shadow: none;
}

#PersonaManagement :is(input:not([type="range"]), textarea, select, option, optgroup) {
  color: var(--ningye-ink);
  background: rgba(252, 249, 236, .97);
  border: 1px solid var(--ningye-line);
}

#PersonaManagement .avatar-container,
#PersonaManagement .persona_block {
  background: rgba(238, 233, 211, .6);
  border: 1px dashed var(--ningye-line);
  border-radius: var(--ningye-radius-sm);
}

#PersonaManagement .avatar img { border-radius: .22rem; border: .24rem solid var(--ningye-paper); box-shadow: var(--ningye-shadow-soft); }
#PersonaManagement :is(.menu_button, button) { color: var(--ningye-sage); background: rgba(230, 226, 202, .8); border-color: var(--ningye-line); }

/* ===== src/windows/characters.css ===== */
/* W12 — character archive. */
#right-nav-panel {
  color: var(--ningye-ink);
  background-color: var(--ningye-paper-panel);
  background-image: var(--ningye-paper-image);
  background-size: cover;
  background-position: right top;
  border: 1px solid var(--ningye-line);
  box-shadow: var(--ningye-shadow);
  backdrop-filter: none;
}

#right-nav-panel :is(h3, h4, .inline-drawer-header, .ch_name) { color: var(--ningye-sage); font-weight: 400; }

#right-nav-panel .standoutHeader {
  color: var(--ningye-sage);
  background-color: #ded3b3;
  background-image: none;
  border: 1px solid var(--ningye-line-soft);
  border-left: .22rem solid var(--ningye-citrus);
  border-radius: var(--ningye-radius-sm);
  box-shadow: var(--ningye-shadow-soft);
  filter: none;
  opacity: 1;
  text-shadow: none;
}

#right-nav-panel .standoutHeader :is(span, strong, b, i, .fa-solid) {
  color: inherit;
  filter: none;
  opacity: 1;
  text-shadow: none;
}

#right-nav-panel .standoutHeader ~ .inline-drawer-content {
  color: var(--ningye-ink);
  background-color: #e7ddbf;
  background-image: none;
  border-color: var(--ningye-line-soft);
  box-shadow: none;
  filter: none;
  opacity: 1;
  text-shadow: none;
}

#right-nav-panel :is(input:not([type="range"]), textarea, select, option, optgroup) {
  color: var(--ningye-ink);
  background: rgba(252, 249, 236, .97);
  border: 1px solid var(--ningye-line);
}

#right-nav-panel :is(.character_select, .group_select, .bogus_folder_select) {
  background: rgba(238, 233, 211, .62);
  border: 1px solid var(--ningye-line-soft);
  border-radius: var(--ningye-radius-sm);
}

#right-nav-panel .avatar img { border-radius: .22rem; border: .22rem solid var(--ningye-paper); box-shadow: var(--ningye-shadow-soft); }
#right-nav-panel :is(.menu_button, button) { color: var(--ningye-sage); background: rgba(230, 226, 202, .8); border-color: var(--ningye-line); }
#right-nav-panel :is(.menu_button, button):hover { color: var(--ningye-clay); background: rgba(217, 199, 95, .2); }

/* ===== src/windows/popup-notification.css ===== */
/* W13 — paper slips and semantic stamps. */
.popup {
  color: var(--ningye-ink);
  background-color: var(--ningye-paper-panel);
  background-image: var(--ningye-paper-image);
  background-size: cover;
  border: 1px solid var(--ningye-line);
  border-radius: var(--ningye-radius);
  box-shadow: 0 1rem 3rem rgba(43, 54, 34, .28);
  backdrop-filter: none;
}

.popup .popup-content,
.popup .popup-body { color: var(--ningye-ink); background: transparent; }
.popup :is(input:not([type="range"]), textarea, select, option, optgroup) {
  color: var(--ningye-ink);
  background: rgba(252, 249, 236, .97);
  border: 1px solid var(--ningye-line);
}

.popup :is(.menu_button, button) { color: var(--ningye-sage); background: rgba(230, 226, 202, .86); border-color: var(--ningye-line); }
.popup :is(.menu_button, button):hover { color: var(--ningye-clay); background: rgba(217, 199, 95, .22); }

body > #toast-container > div,
body #toast-container > div {
  color: var(--ningye-ink);
  background-color: rgba(248, 244, 227, .98);
  background-image: none !important;
  background-repeat: no-repeat !important;
  border: 1px solid var(--ningye-line);
  border-left-width: .28rem;
  border-radius: var(--ningye-radius-sm);
  box-shadow: var(--ningye-shadow);
  text-shadow: none;
  opacity: 1;
}

body #toast-container .toast-success { border-left-color: var(--ningye-success); }
body #toast-container .toast-error { border-left-color: var(--ningye-error); }
body #toast-container .toast-info { border-left-color: var(--ningye-info); }
body #toast-container .toast-warning { border-left-color: var(--ningye-warning); }
body #toast-container .toast-title { color: var(--ningye-sage); font-weight: 400; letter-spacing: .04em; }
body #toast-container .toast-close-button { color: var(--ningye-clay); opacity: .88; }

.select2-container .select2-dropdown {
  color: var(--ningye-ink);
  background: var(--ningye-paper-panel);
  border-color: var(--ningye-line);
}

.select2-container .select2-results__option--highlighted,
.select2-container .select2-results__option[aria-selected="true"] {
  color: var(--ningye-ink);
  background: rgba(217, 199, 95, .25);
}

/* ===== src/windows/micro-controls.css ===== */
/* Shared visual tokens, bounded to the eleven verified functional roots. */
:is(
  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel,
  .popup
) input[type="checkbox"],
:is(
  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel,
  .popup
) input[type="radio"] {
  accent-color: var(--ningye-sage);
}

/* SillyTavern draws checkboxes itself, so accent-color alone does not recolor them. */
:is(
  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel,
  .popup
) input[type="checkbox"] {
  color: var(--ningye-ink);
  background-color: #e2d7b7;
  border: 1px solid var(--ningye-sage);
  outline: 1px solid rgba(79, 101, 66, .2);
  box-shadow: inset 0 0 0 1px rgba(249, 245, 226, .72);
  filter: none;
  opacity: 1;
}

:is(
  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel,
  .popup
) input[type="checkbox"]::before {
  box-shadow: inset 1em 1em var(--ningye-ink);
  filter: none;
}

:is(
  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel,
  .popup
) input[type="checkbox"]:checked {
  background-color: var(--ningye-citrus);
  border-color: var(--ningye-sage);
  box-shadow: inset 0 0 0 1px rgba(255, 248, 199, .62), var(--ningye-shadow-soft);
}

:is(
  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel,
  .popup
) input[type="checkbox"]:hover:not(:disabled) {
  border-color: var(--ningye-clay);
  box-shadow: inset 0 0 0 1px rgba(255, 248, 199, .62), var(--ningye-glow-soft);
}

:is(
  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel,
  .popup
) input[type="checkbox"]:disabled {
  color: #65715e;
  background-color: #cfc7ad;
  border-color: rgba(79, 101, 66, .42);
  box-shadow: none;
  filter: none;
  opacity: 1;
}

:is(
  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel,
  .popup
) input[type="range"] {
  accent-color: var(--ningye-sage);
}

:is(
  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel,
  .popup
) input[type="range"]::-webkit-slider-thumb {
  background: var(--ningye-citrus);
  border: 1px solid var(--ningye-sage);
  box-shadow: 0 0 0 .16rem rgba(245, 240, 223, .88), var(--ningye-glow-soft);
}

:is(
  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel,
  .popup
) :disabled {
  color: #828878;
  opacity: .72;
}

:is(
  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel,
  .popup
) ::-webkit-scrollbar-thumb,
#chat::-webkit-scrollbar-thumb {
  background: var(--ningye-sage-light);
  border: 2px solid var(--ningye-paper);
  border-radius: 999px;
}

/* ===== src/windows/mobile.css ===== */
/* W14 — single flat page mobile degradation; official drawer geometry retained. */
@media (max-width: 700px) {
  :root {
    --ningye-avatar-size: 3.2rem;
    --ningye-avatar-gap: .55rem;
    --ningye-avatar-slot: calc(var(--ningye-avatar-size) + var(--ningye-avatar-gap));
    --ningye-avatar-head-height: calc(var(--ningye-avatar-size) + 2rem);
  }

  body #chat {
    padding: .8rem .72rem 1rem;
    background-color: #e9dfc2;
    background-image: none;
    background-size: auto;
    border-radius: 0;
  }

  #chat .mes {
    width: 100%;
    padding-block: .8rem 1rem;
  }

  #chat .mes[is_user="true"] .mes_block {
    width: 100%;
    padding: .7rem .72rem .8rem;
  }

  #chat .ch_name {
    min-height: var(--ningye-avatar-head-height);
    padding-right: var(--ningye-avatar-slot);
  }

  #chat .mesAvatarWrapper { top: .8rem; right: 0; }
  #chat .mes + .mes[is_system="false"] .mesAvatarWrapper {
    top: calc(.8rem + 1rem + 1px);
  }

  #chat .mes_text { font-size: .98em; line-height: 1.78; }
  #chat .mes[is_user="false"][is_system="false"] .mes_text > p { text-indent: 1.6em; }

  #top-settings-holder {
    padding-inline: .1rem;
  }

  #send_form {
    min-width: 0;
    border-radius: 0;
    font-size: 1rem;
    -webkit-text-size-adjust: 100%;
    text-size-adjust: 100%;
  }

  #send_form #nonQRFormItems {
    align-items: flex-end;
    flex-wrap: nowrap;
    min-width: 0;
  }

  #send_form #leftSendForm,
  #send_form #rightSendForm {
    flex: 0 0 auto;
    flex-wrap: nowrap;
    align-items: flex-end;
    width: auto;
    min-width: 0;
  }

  #send_form #send_textarea {
    box-sizing: border-box;
    flex: 1 1 0;
    width: auto;
    min-width: 0;
    max-width: 100%;
    padding-inline: .45rem;
    font-size: 1rem;
    line-height: 1.45;
  }

  #send_form #send_textarea::placeholder {
    font-size: 1rem;
    line-height: 1.45;
    text-align: left;
  }

  #left-nav-panel,
  #right-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement {
    background-color: rgba(247, 242, 224, .99);
    background-size: auto 100%;
    border-radius: 0;
  }

  .popup {
    max-width: calc(100dvw - 1rem);
    max-height: calc(100dvh - 1rem);
    border-radius: var(--ningye-radius-sm);
  }

  #chat .mes_text pre,
  #chat .mes_text table { max-width: 100%; overflow-x: auto; }
}

/* ===== src/fallback.css ===== */
/* Remote font/image failure must never decide layout or interaction. */

#chat,
#top-settings-holder,
#send_form,
.drawer-content,
.popup {
  background-color: var(--ningye-paper);
}

#chat .avatar img {
  background: var(--ningye-paper-deep);
}

#top-settings-holder .drawer-icon.fa-solid,
#top-settings-holder .drawer-icon.fas,
#leftSendForm > div,
#rightSendForm > div {
  color: var(--ningye-sage);
  opacity: .88;
}

#top-settings-holder .drawer-icon.fa-solid::before,
#top-settings-holder .drawer-icon.fas::before,
#leftSendForm > div::before,
#rightSendForm > div::before {
  visibility: visible;
}
